def _imutabilidade_auditoria() -> None:
    """A trilha de auditoria só aceita inserções (RF-SEG-03)."""
    op.execute(
        "CREATE TRIGGER trg_auditoria_sem_update BEFORE UPDATE ON auditoria "
        "BEGIN SELECT RAISE(ABORT, 'auditoria: registros não podem ser alterados'); END"
    )
    op.execute(
        "CREATE TRIGGER trg_auditoria_sem_delete BEFORE DELETE ON auditoria "
        "BEGIN SELECT RAISE(ABORT, 'auditoria: registros não podem ser excluídos'); END"
    )


PERMISSOES = {
    "usuario:gerenciar": "Criar, alterar, desativar usuários e redefinir senhas",
    "arquivo:enviar": "Enviar arquivos originais",
    "arquivo:ler": "Consultar e baixar arquivos",
    "auditoria:ler": "Consultar a trilha de auditoria",
}

PAPEIS = {
    "ADMIN": ("Administrador", "Acesso total, inclusive usuários", list(PERMISSOES)),
    "REVISOR": ("Geólogo revisor", "Registra e aprova registros geológicos",
                ["arquivo:enviar", "arquivo:ler", "auditoria:ler"]),
    "GEOLOGO": ("Geólogo", "Registra mapeamentos, amostras e arquivos", ["arquivo:enviar", "arquivo:ler"]),
    "TECNICO": ("Técnico / amostrador", "Registra amostras e fotos", ["arquivo:enviar", "arquivo:ler"]),
    "CONSULTA": ("Consulta", "Somente leitura", ["arquivo:ler"]),
}


def _dados_iniciais() -> None:
    t_perm = sa.table("permissao", sa.column("id", sa.Uuid), sa.column("codigo", sa.String),
                      sa.column("descricao", sa.String))
    t_papel = sa.table("papel", sa.column("id", sa.Uuid), sa.column("codigo", sa.String),
                       sa.column("nome", sa.String), sa.column("descricao", sa.String))
    t_pp = sa.table("papel_permissao", sa.column("papel_id", sa.Uuid), sa.column("permissao_id", sa.Uuid))
    t_par = sa.table("parametro_sistema", sa.column("chave", sa.String), sa.column("valor", sa.String))

    ids_perm = {c: uuid.uuid4() for c in PERMISSOES}
    op.bulk_insert(t_perm, [{"id": ids_perm[c], "codigo": c, "descricao": d} for c, d in PERMISSOES.items()])
    linhas_papel, linhas_pp = [], []
    for codigo, (nome, desc, perms) in PAPEIS.items():
        pid = uuid.uuid4()
        linhas_papel.append({"id": pid, "codigo": codigo, "nome": nome, "descricao": desc})
        linhas_pp += [{"papel_id": pid, "permissao_id": ids_perm[p]} for p in perms]
    op.bulk_insert(t_papel, linhas_papel)
    op.bulk_insert(t_pp, linhas_pp)
    # Identificador desta instalação: base da futura sincronização com tablets/celulares.
    op.bulk_insert(t_par, [{"chave": "instalacao_id", "valor": str(uuid.uuid4())}])
